ansform: uppercase;\n    font-size: 15px;\n    font-weight: 600;\n    letter-spacing: 1px;\n}\n\n\n/* =========================================\n   SHOP.CO Header Actions\n   ========================================= */\n\n.shopco-header-actions {\n	display: flex;\n	align-items: center;\n	gap: 18px;\n	margin-left: 20px;\n}\n\n\n/* =========================================\n   Search\n   ========================================= */\n\n.shopco-header-search {\n	position: relative;\n	display: flex;\n	align-items: center;\n	width: 28vw;\n	height: 40px;\n	margin: 0;\n	padding: 0;\n}\n\n.shopco-header-search input[type=\"search\"] {\n	width: 100%;\n	height: 40px;\n	margin: 0;\n	padding: 0 16px 0 45px;\n\n	border: 0;\n	border-radius: 24px;\n\n	background: #f2f2f2;\n	color: #000;\n\n	font-family: \"Satoshi\", sans-serif;\n	font-size: 14px;\n\n	outline: none;\n	box-shadow: none;\n}\n\n.shopco-header-search input[type=\"search\"]::placeholder {\n	color: #777;\n}\n\n.shopco-header-search button {\n	position: absolute;\n	top: 50%;\n	left: 12px;\n\n	display: flex;\n	align-items: center;\n	justify-content: center;\n\n	width: 24px;\n	height: 24px;\n\n	margin: 0;\n	padding: 0;\n\n	border: 0;\n	background: transparent;\n\n	color: #000;\n\n	transform: translateY(-50%);\n	cursor: pointer;\n}\n\n.shopco-header-search button:hover,\n.shopco-header-search button:focus {\n	background: transparent;\n	color: #000;\n}\n\n\n/* =========================================\n   Cart + Account\n   ========================================= */\n\n.shopco-header-cart,\n.shopco-header-account {\n	position: relative;\n\n	display: flex;\n	align-items: center;\n	justify-content: center;\n\n	width: 24px;\n	height: 24px;\n\n	margin: 0;\n	padding: 0;\n\n	color: #000;\n	text-decoration: none;\n}\n\n.shopco-header-cart:hover,\n.shopco-header-account:hover {\n	color: #555;\n}\n\n.shopco-header-cart svg,\n.shopco-header-account svg {\n	display: block;\n	width: 24px;\n	height: 24px;\n}\n\n\n/* =========================================\n   Cart Count\n   ========================================= */\n\n.shopco-cart-count {\n	position: absolute;\n\n	top: -9px;\n	right: -9px;\n\n	display: flex;\n	align-items: center;\n	justify-content: center;\n\n	min-width: 16px;\n	height: 16px;\n\n	padding: 0 4px;\n\n	border-radius: 50%;\n\n	background: #000;\n	color: #fff;\n\n	font-family: \"Satoshi\", sans-serif;\n	font-size: 9px;\n	font-weight: 500;\n	line-height: 1;\n}\n\n\n/* =========================================\n   Tablet\n   ========================================= */\n\n@media (max-width: 1024px) {\n\n	.shopco-header-actions {\n		gap: 14px;\n		margin-left: 14px;\n	}\n\n	.shopco-header-search {\n		width: 180px;\n	}\n\n}\n\n\n/* =========================================\n   Mobile\n   ========================================= */\n\n@media (max-width: 768px) {\n\n	.shopco-header-actions {\n		width: 100%;\n		margin: 15px 0 0;\n		padding: 0;\n		gap: 14px;\n	}\n\n	.shopco-header-search {\n		flex: 1;\n		width: auto;\n	}\n\n	.shopco-header-search input[type=\"search\"] {\n		height: 42px;\n	}\n\n	.shopco-header-cart,\n	.shopco-header-account {\n		flex: 0 0 24px;\n	}\n\n}','astra-child','','inherit','closed','closed','','50-revision-v1','','','2026-08-31 13:56:09','2026-08-31 13:56:09','',50,'https://shop.local:8890/?p=182',0,'revision','',0),(183,1,'2026-08-31 13:58:19','2026-08-31 13:58:19','<h2>FIND CLOTHES THAT MATCHES YOUR STYLE</h2>		Browse through our diverse range of meticulously crafted garments, designed to bring out your individuality and cater to your sense of style.								<a href=\"#\">\n									Shop Now\n					</a>\n			International Brands			\n				0\n				+\n			High-Quality Products			\n				0\n				+\n			Happy Customers			\n				0\n				+\n																	<img width=\"959\" height=\"1024\" src=\"https://shop.local:8890/wp-content/uploads/2026/08/b26fea69ccfd8aa5825862cdb9604a4fb4930464-scaled-e1788180600981-959x1024.jpg\" alt=\"\" srcset=\"https://shop.local:8890/wp-content/upl