rt Count\n   ========================================= */\n\n.shopco-cart-count {\n	position: absolute;\n\n	top: -9px;\n	right: -9px;\n\n	display: flex;\n	align-items: center;\n	justify-content: center;\n\n	min-width: 16px;\n	height: 16px;\n\n	padding: 0 4px;\n\n	border-radius: 50%;\n\n	background: #000;\n	color: #fff;\n\n	font-family: \"Satoshi\", sans-serif;\n	font-size: 9px;\n	font-weight: 500;\n	line-height: 1;\n}\n\n\n/* =========================================\n   Tablet\n   ========================================= */\n\n@media (max-width: 1024px) {\n\n	.shopco-header-actions {\n		gap: 14px;\n		margin-left: 14px;\n	}\n\n	.shopco-header-search {\n		width: 180px;\n	}\n\n}\n\n\n/* =========================================\n   Mobile\n   ========================================= */\n\n@media (max-width: 768px) {\n	\n	\n	.ast-header-break-point #masthead .ast-mobile-header-wrap .ast-primary-header-bar{\n		\n		padding-left:5px !important;\n			padding-right:5px !important;\n		\n	}\n	\n	button.shopco-mobile-search-toggle {\n    box-shadow: none;\n}\n	\n.site-branding.ast-site-identity {\n    padding: 15px 0px 10px !important;\n}\n	.site-footer-section:nth-child(1) {\n    margin-bottom: 30px !important;\n}\n.site-footer-section:not(.site-footer-section:nth-child(1)) {\n    width: 40%;\n}\n	\n	.ast-builder-footer-grid-columns.site-primary-footer-inner-wrap.ast-builder-grid-row {\n    display: flex;\n    float: left;\n    flex-direction: row;\n    flex-wrap: wrap;\n}\n	\n	.ast-builder-footer-grid-columns.site-below-footer-inner-wrap.ast-builder-grid-row {\n    grid-template-columns: 1fr;\n}\n	.site-below-footer-wrap.ast-builder-grid-row-container.site-footer-focus-item.ast-builder-grid-row-2-equal.ast-builder-grid-row-tablet-2-equal.ast-builder-grid-row-mobile-full.ast-footer-row-stack.ast-footer-row-tablet-stack.ast-footer-row-mobile-stack .site-footer-below-section-2.site-footer-section.site-footer-section-2 {\n    width: 100%;\n}\n	\n	\n	.ast-footer-html-1 .ast-buil